// Normalise a raw Notion page into flat fields + ready-made Slack blocks.
// Property names are matched case-insensitively so the workflow survives
// small differences between task databases.

const plain = (arr) => (arr || []).map((t) => t.plain_text).join('').trim();

const pick = (props, ...names) => {
  const keys = Object.keys(props);
  for (const name of names) {
    const key = keys.find((k) => k.toLowerCase() === name.toLowerCase());
    if (key) return props[key];
  }
  return undefined;
};

const readText = (p) => (p ? plain(p.title) || plain(p.rich_text) : '');
const readChoice = (p) => p?.select?.name || p?.status?.name || '';
const readMulti = (p) => (p?.multi_select || []).map((o) => o.name).join(', ');
const readPeople = (p) =>
  (p?.people || [])
    .map((u) => u.name || u.person?.email)
    .filter(Boolean)
    .join(', ');
const readDate = (p) => p?.date?.start || '';

const prettyDate = (iso) => {
  if (!iso) return '';
  // Notion sends due dates as plain 'YYYY-MM-DD'. Parsing those as UTC and then
  // formatting in local time shifts the day backwards west of UTC, so pin them.
  const dateOnly = !iso.includes('T');
  const d = new Date(dateOnly ? `${iso}T00:00:00Z` : iso);
  if (Number.isNaN(d.getTime())) return iso;
  const opts = dateOnly
    ? { year: 'numeric', month: 'short', day: 'numeric', timeZone: 'UTC' }
    : { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' };
  return d.toLocaleDateString('en-US', opts);
};

const PRIORITY_EMOJI = {
  urgent: ':rotating_light:',
  high: ':red_circle:',
  medium: ':large_yellow_circle:',
  low: ':large_blue_circle:',
};

const results = [];

for (const item of $input.all()) {
  const page = item.json;
  const props = page.properties || {};

  // The title column can be named anything, so find it by type first.
  const titleKey = Object.keys(props).find((k) => props[k]?.type === 'title');
  const title = titleKey ? plain(props[titleKey].title) : '';

  const status = readChoice(pick(props, 'Status', 'State'));
  const priority = readChoice(pick(props, 'Priority', 'Urgency'));
  const assignee = readPeople(pick(props, 'Assignee', 'Owner', 'Assigned to'));
  const dueDate = readDate(pick(props, 'Due Date', 'Due', 'Deadline'));
  const project = readChoice(pick(props, 'Project', 'Epic')) || readMulti(pick(props, 'Project'));
  const tags = readMulti(pick(props, 'Tags', 'Labels'));
  const notes = readText(pick(props, 'Notes', 'Description', 'Summary'));

  const createdBy = page.created_by?.name || '';
  const url = page.url || '';
  const emoji = PRIORITY_EMOJI[priority.toLowerCase()] || ':memo:';

  const fields = [];
  const addField = (label, value) => {
    if (value) fields.push({ type: 'mrkdwn', text: `*${label}*\n${value}` });
  };

  addField('Status', status);
  addField('Priority', priority);
  addField('Assignee', assignee);
  addField('Due', prettyDate(dueDate));
  addField('Project', project);
  addField('Tags', tags);

  const blocks = [
    {
      type: 'header',
      text: { type: 'plain_text', text: `${emoji} New task: ${title || 'Untitled'}`.slice(0, 150), emoji: true },
    },
  ];

  // Slack allows at most 10 fields in one section.
  if (fields.length) {
    blocks.push({ type: 'section', fields: fields.slice(0, 10) });
  }

  if (notes) {
    blocks.push({
      type: 'section',
      text: { type: 'mrkdwn', text: notes.length > 2800 ? `${notes.slice(0, 2800)}…` : notes },
    });
  }

  if (url) {
    blocks.push({
      type: 'actions',
      elements: [
        {
          type: 'button',
          text: { type: 'plain_text', text: 'Open in Notion', emoji: true },
          url,
          style: 'primary',
        },
      ],
    });
  }

  blocks.push({
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text: `Created${createdBy ? ` by ${createdBy}` : ''} · ${prettyDate(page.created_time) || 'just now'}`,
      },
    ],
  });

  results.push({
    json: {
      pageId: page.id,
      title,
      status,
      priority,
      assignee,
      dueDate,
      project,
      tags,
      notes,
      url,
      createdBy,
      createdTime: page.created_time,
      fallbackText: `New task: ${title || 'Untitled'}${assignee ? ` — ${assignee}` : ''}`,
      slackPayload: { blocks, text: `New task: ${title || 'Untitled'}` },
    },
  });
}

return results;
